MAP
    NAME "SS_MAP_PTAR_SAPAL"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB 
	CONFIG "MS_ERRORFILE" "/srv/mapserver/err_ptar_sapal.log"
    DEBUG 0
    SYMBOL
        NAME "trianguloverde"
        TYPE pixmap
        IMAGE "includes/symbols/TrianguloVerde.png"
    END #SYMBOL
        LAYER
            NAME "SS_MAP_PTAR_SAPAL"
            PROJECTION
			'init=epsg:32614'
		END #PROJECTION
            CONNECTIONTYPE POSTGIS
            STATUS DEFAULT
            INCLUDE 'includes/conexion.map'
            DATA "gm_planta_tratamiento from (select gm_planta_tratamiento, id_planta_tratamiento, nb_planta_tratamiento, cl_administracion_planta from l_plantas_tratamiento where cl_administracion_planta=1)as c using unique id_planta_tratamiento using srid=32614"
            TYPE POINT
            LABELITEM "nb_planta_tratamiento"
            LABELCACHE on
            CLASS
                NAME "PTAR's Sapal"
                STYLE
                    SYMBOL "TrianguloVerde"
                    SIZE 18
                    OPACITY 75
                END #STYLE
                LABEL
                    TYPE TRUETYPE
                    FONT "arial"
                    ALIGN RIGHT
                    OFFSET 0 25
                    SIZE 15
                    COLOR 8 59 130
                    OUTLINECOLOR 0 0 0
                END #LABEL
            END #CLASS
        END #LAYER
END #MAP